-- 12A step 1 of 2 APPLY: private.door_checkin_core (new, no grants) + hardened public.event_checkin_scan
-- 12A DOOR HARDENING: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/12a-door-hardening/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL without Joe's relayed yes + a Sentinel pass at the exact commit + a VERIFIED backup (single definition: db/proposed/13a-orders-hardening/RUNBOOK-APPLY-BACKUP-ROLLBACK.md section 2). Sentinel's conditions in atlas/checkin-scan-fix.md were NOT available and are UNREVIEWED.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Creates: private.door_checkin_core(text); creates schema private ONLY if it does not exist (prod HAS it: four postgres-only incident tables, which are left untouched and fingerprint-checked). Replaces: public.event_checkin_scan(text). Does NOT touch check_in_ticket (step 2).
-- Run it a second time and it refuses at the guard (scan no longer original) with nothing changed.
BEGIN;
-- repo-wide pack key (same as R1 #136): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded; a timeout set after a lock statement cannot bound that statement) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- 1. DRIFT GUARD: live state must be EXACTLY the captured prod state S0 (scan body md5, config, ACL; event_orders columns/ACL/policies/constraints; schema private either absent or exactly the four known postgres-only tables with no client access and nothing else).
DO $guard$
DECLARE
  f text[] := ARRAY[]::text[];
  v text;
BEGIN
  IF current_user <> 'postgres' THEN f := f || ('run as postgres; current_user=' || current_user); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('public') AND p.proname = 'event_checkin_scan'), 'ABSENT');
  IF v IS DISTINCT FROM '1' THEN f := f || ('scan.overloads: expected 1 but live is ' || v); END IF;
  v := coalesce((SELECT md5(p.prosrc) FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM '566910baa68086daf08323a562922c7f' THEN f := f || ('scan.src_md5: expected 566910baa68086daf08323a562922c7f but live is ' || v); END IF;
  v := coalesce((SELECT coalesce((SELECT string_agg(c,',') FROM unnest(p.proconfig) c),'(none)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'search_path=public' THEN f := f || ('scan.config: expected search_path=public but live is ' || v); END IF;
  v := coalesce((SELECT p.prosecdef::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('scan.secdef: expected true but live is ' || v); END IF;
  v := coalesce((SELECT pg_get_userbyid(p.proowner)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'postgres' THEN f := f || ('scan.owner: expected postgres but live is ' || v); END IF;
  v := coalesce((SELECT (SELECT l.lanname FROM pg_language l WHERE l.oid=p.prolang)::text||'/'||p.prorettype::regtype::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'plpgsql/jsonb' THEN f := f || ('scan.lang_ret: expected plpgsql/jsonb but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(CASE WHEN p.proacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(p.proacl) acl_e) END,'(default)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM '{authenticated=X/postgres,postgres=X/postgres,service_role=X/postgres}' THEN f := f || ('scan.acl_sorted: expected {authenticated=X/postgres,postgres=X/postgres,service_role=X/postgres} but live is ' || v); END IF;
  v := coalesce((SELECT has_function_privilege('anon', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'false' THEN f := f || ('scan.exec_anon: expected false but live is ' || v); END IF;
  v := coalesce((SELECT has_function_privilege('authenticated', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('scan.exec_authenticated: expected true but live is ' || v); END IF;
  v := coalesce((SELECT has_function_privilege('service_role', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('scan.exec_service_role: expected true but live is ' || v); END IF;
  v := coalesce((SELECT coalesce((SELECT bool_or(x.grantee = 0) FROM aclexplode(p.proacl) x), false)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT');
  IF v IS DISTINCT FROM 'false' THEN f := f || ('scan.exec_public: expected false but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.pronamespace = to_regnamespace('private') AND p.proname = 'door_checkin_core'), 'ABSENT');
  IF v IS DISTINCT FROM '0' THEN f := f || ('core.overloads: expected 0 but live is ' || v); END IF;
  v := coalesce(coalesce((SELECT nullif(concat_ws(' ; ',
    CASE WHEN s.nspowner <> to_regrole('postgres') THEN 'schema owner is not postgres' END,
    (SELECT 'known incident tables partially present (' || count(*) || ' of 4)' FROM pg_class c WHERE c.relnamespace = s.oid AND c.relkind = 'r' AND c.relname = ANY (ARRAY['incident_auth_counts_20261106','incident_session_ids_20261106','incident_refresh_ids_20261106','qr_token_backup_20261106']::name[]) HAVING count(*) NOT IN (0, 4)),
    (SELECT 'known incident table(s) with unexpected owner / ACL / column ACL: ' || string_agg(c.relname::text, ', ' ORDER BY c.relname::text) FROM pg_class c WHERE c.relnamespace = s.oid AND c.relkind = 'r' AND c.relname = ANY (ARRAY['incident_auth_counts_20261106','incident_session_ids_20261106','incident_refresh_ids_20261106','qr_token_backup_20261106']::name[]) AND (c.relowner <> to_regrole('postgres') OR coalesce(c.relacl::text, '{postgres=arwdDxtm/postgres}') <> '{postgres=arwdDxtm/postgres}' OR EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attacl IS NOT NULL))),
    (SELECT 'unexpected function(s): ' || string_agg(p.oid::regprocedure::text, ', ' ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace = s.oid),
    (SELECT 'unexpected relation(s): ' || string_agg(c.relname::text || '/' || c.relkind::text, ', ' ORDER BY c.relname::text) FROM pg_class c WHERE c.relnamespace = s.oid AND NOT ((c.relkind = 'r' AND c.relname = ANY (ARRAY['incident_auth_counts_20261106','incident_session_ids_20261106','incident_refresh_ids_20261106','qr_token_backup_20261106']::name[])) OR (c.relkind = 'i' AND EXISTS (SELECT 1 FROM pg_index i JOIN pg_class t ON t.oid = i.indrelid WHERE i.indexrelid = c.oid AND t.relnamespace = s.oid AND t.relname = ANY (ARRAY['incident_auth_counts_20261106','incident_session_ids_20261106','incident_refresh_ids_20261106','qr_token_backup_20261106']::name[]))) OR (c.relkind = 'S' AND EXISTS (SELECT 1 FROM pg_depend d JOIN pg_class t ON t.oid = d.refobjid WHERE d.classid = 'pg_class'::regclass AND d.refclassid = 'pg_class'::regclass AND d.objid = c.oid AND d.deptype IN ('a','i') AND t.relnamespace = s.oid AND t.relname = ANY (ARRAY['incident_auth_counts_20261106','incident_session_ids_20261106','incident_refresh_ids_20261106','qr_token_backup_20261106']::name[]))))),
    (SELECT 'unexpected type(s): ' || string_agg(ty.typname::text, ', ' ORDER BY ty.typname::text) FROM pg_type ty WHERE ty.typnamespace = s.oid AND NOT ((ty.typtype = 'c' AND EXISTS (SELECT 1 FROM pg_class t WHERE t.oid = ty.typrelid AND t.relnamespace = s.oid)) OR (ty.typcategory = 'A' AND EXISTS (SELECT 1 FROM pg_type e WHERE e.oid = ty.typelem AND e.typtype = 'c' AND e.typnamespace = s.oid)))),
    (SELECT 'unexpected collation / operator / conversion / statistics object(s): ' || ((SELECT count(*) FROM pg_collation WHERE collnamespace = s.oid) + (SELECT count(*) FROM pg_operator WHERE oprnamespace = s.oid) + (SELECT count(*) FROM pg_conversion WHERE connamespace = s.oid) + (SELECT count(*) FROM pg_statistic_ext WHERE stxnamespace = s.oid))::text WHERE (SELECT count(*) FROM pg_collation WHERE collnamespace = s.oid) + (SELECT count(*) FROM pg_operator WHERE oprnamespace = s.oid) + (SELECT count(*) FROM pg_conversion WHERE connamespace = s.oid) + (SELECT count(*) FROM pg_statistic_ext WHERE stxnamespace = s.oid) > 0)), '') FROM pg_namespace s WHERE s.oid = to_regnamespace('private')), 'ok'), 'ABSENT');
  IF v IS DISTINCT FROM 'ok' THEN f := f || ('private.contents: expected ok but live is ' || v); END IF;
  v := coalesce(coalesce(nullif(concat_ws(' ; ',
    (SELECT 'schema privilege ' || string_agg(cr.r || ':' || p, ',') FROM (SELECT rolname::text AS r FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) cr, unnest(ARRAY['USAGE','CREATE']) p WHERE has_schema_privilege(cr.r, to_regnamespace('private')::oid, p)),
    (SELECT 'schema ACL names PUBLIC' FROM pg_namespace n, aclexplode(n.nspacl) x WHERE n.oid = to_regnamespace('private') AND x.grantee = 0 LIMIT 1),
    (SELECT 'relation privilege ' || string_agg(DISTINCT c.relname::text || '/' || cr.r, ',') FROM pg_class c, (SELECT rolname::text AS r FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')) cr WHERE c.relnamespace = to_regnamespace('private') AND c.relkind IN ('r','v','m','S','p','f') AND has_table_privilege(cr.r, c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')),
    (SELECT 'relation ACL names PUBLIC: ' || string_agg(DISTINCT c.relname::text, ',') FROM pg_class c, aclexplode(c.relacl) x WHERE c.relnamespace = to_regnamespace('private') AND x.grantee = 0),
    (SELECT 'default ACL entries in private granting to PUBLIC / client roles: ' || count(*)::text FROM pg_default_acl d, aclexplode(d.defaclacl) x WHERE d.defaclnamespace = to_regnamespace('private') AND (x.grantee = 0 OR x.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role'))) HAVING count(*) > 0)), ''), 'none'), 'ABSENT');
  IF v IS DISTINCT FROM 'none' THEN f := f || ('private.client_access: expected none but live is ' || v); END IF;
  v := coalesce((SELECT c.relkind::text||'/'||c.relrowsecurity::text||'/'||c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT');
  IF v IS DISTINCT FROM 'r/true/false' THEN f := f || ('orders.relkind_rls: expected r/true/false but live is ' || v); END IF;
  v := coalesce((SELECT md5(string_agg(a.attname::text||':'||format_type(a.atttypid,a.atttypmod), ',' ORDER BY a.attname::text COLLATE "C")) FROM pg_attribute a WHERE a.attrelid = 'public.event_orders'::regclass AND a.attnum > 0 AND NOT a.attisdropped), 'ABSENT');
  IF v IS DISTINCT FROM '466de103365b91e19b05b5d29da153ad' THEN f := f || ('orders.columns_md5: expected 466de103365b91e19b05b5d29da153ad but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT');
  IF v IS DISTINCT FROM '{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}' THEN f := f || ('orders.acl_sorted: expected {anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres} but live is ' || v); END IF;
  v := coalesce((SELECT md5(string_agg(x, ',' ORDER BY x COLLATE "C")) FROM (SELECT p.policyname::text||'|'||p.cmd||'|'||(SELECT string_agg(r::text, ',' ORDER BY r::text COLLATE "C") FROM unnest(p.roles) r)||'|'||p.permissive AS x FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'event_orders') s), 'ABSENT');
  IF v IS DISTINCT FROM '328eefa85ed838c92611a30808ff9a9a' THEN f := f || ('orders.policies_md5: expected 328eefa85ed838c92611a30808ff9a9a but live is ' || v); END IF;
  v := coalesce((SELECT string_agg(x, ',' ORDER BY x COLLATE "C") FROM (SELECT c.contype::text||':'||coalesce((SELECT relname::text FROM pg_class WHERE oid = c.confrelid),'-')||':'||coalesce(nullif(c.confdeltype::text,' '),'-')||':'||(SELECT string_agg(a.attname::text, '+' ORDER BY a.attname::text COLLATE "C") FROM pg_attribute a WHERE a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)) AS x FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype IN ('p','f','u','x')) s), 'ABSENT');
  IF v IS DISTINCT FROM 'f:events:c:event_id,f:ticket_tiers:n:tier_id,p:-:-:id' THEN f := f || ('orders.constraints: expected f:events:c:event_id,f:ticket_tiers:n:tier_id,p:-:-:id but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype = 'c' AND pg_get_constraintdef(c.oid) ~ 'pending' AND pg_get_constraintdef(c.oid) ~ 'paid' AND pg_get_constraintdef(c.oid) ~ 'checked_in' AND pg_get_constraintdef(c.oid) ~ 'refunded' AND pg_get_constraintdef(c.oid) ~ 'cancelled' AND (SELECT count(*) FROM regexp_matches(pg_get_constraintdef(c.oid), '''[^'']*''', 'g')) = 5), 'ABSENT');
  IF v IS DISTINCT FROM '1' THEN f := f || ('orders.status_check: expected 1 but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype = 'c'), 'ABSENT');
  IF v IS DISTINCT FROM '1' THEN f := f || ('orders.check_count: expected 1 but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_trigger t WHERE t.tgrelid = 'public.event_orders'::regclass AND NOT t.tgisinternal), 'ABSENT');
  IF v IS DISTINCT FROM '0' THEN f := f || ('orders.user_triggers: expected 0 but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM (VALUES ('events','id'),('events','slug'),('events','title'),('events','owner_handle'),('app_users','id'),('app_users','handle'),('ticket_tiers','id'),('ticket_tiers','name')) v(t,c) WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.'||v.t) AND a.attname = v.c AND NOT a.attisdropped)), 'ABSENT');
  IF v IS DISTINCT FROM '8' THEN f := f || ('deps.columns_present: expected 8 but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.oid = to_regprocedure('auth.uid()')), 'ABSENT');
  IF v IS DISTINCT FROM '1' THEN f := f || ('deps.auth_uid: expected 1 but live is ' || v); END IF;
  IF array_length(f, 1) IS NOT NULL THEN
    RAISE EXCEPTION '12A APPLY-01: DRIFT, ABORT, nothing applied. % mismatch(es): %', array_length(f, 1), array_to_string(f, ' ; ');
  END IF;
END
$guard$;

-- 2. remember the pre-existing private objects (fingerprint of the four known tables + the schema ACL); compared again in the post-check.
DO $fp$
BEGIN
  -- remember the pre-existing private objects exactly as they are NOW (inside this transaction only); the post-check compares
  PERFORM set_config('kil.pack12a.private_fp', (SELECT md5(coalesce(string_agg(x, E'\n' ORDER BY x COLLATE "C"), '')) FROM (SELECT c.relname::text || '|' || c.relkind::text || '|' || pg_get_userbyid(c.relowner)::text || '|' || coalesce(c.relacl::text, '-') || '|' || coalesce((SELECT string_agg(a.attname::text || ':' || format_type(a.atttypid, a.atttypmod) || ':' || coalesce(a.attacl::text, '-'), ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped), '') AS x FROM pg_class c WHERE c.relnamespace = to_regnamespace('private') AND c.relkind = 'r' AND c.relname = ANY (ARRAY['incident_auth_counts_20261106','incident_session_ids_20261106','incident_refresh_ids_20261106','qr_token_backup_20261106']::name[])) z), true);
  PERFORM set_config('kil.pack12a.private_nspacl', coalesce((SELECT coalesce(n.nspacl::text, '(null)') FROM pg_namespace n WHERE n.oid = to_regnamespace('private')), 'ABSENT'), true);
END
$fp$;

-- 3. schema private: CREATE it only when absent (fresh database); an existing schema (prod) is NOT touched. Never dropped by any pack.
DO $schema$
BEGIN
  IF to_regnamespace('private') IS NULL THEN
    CREATE SCHEMA private;
    REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated, service_role;
    RAISE NOTICE '12A: schema private did not exist: created (fresh-database branch)';
  ELSE
    RAISE NOTICE '12A: schema private exists (prod-shaped branch): left untouched; the guard proved its contents';
  END IF;
END
$schema$;
-- default-privilege hardening for objects created in schema private LATER (belt and braces: PostgreSQL cannot remove the global PUBLIC EXECUTE default with an in-schema REVOKE, so the real control is the explicit
-- REVOKE on every object this pack creates; this block makes sure no in-schema default can ever hand out anything to the client roles, and the guard/post-check verify that none exists).
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA private REVOKE ALL ON FUNCTIONS FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA private REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA private REVOKE ALL ON SEQUENCES FROM PUBLIC, anon, authenticated, service_role;
-- the same for role supabase_admin: PostgreSQL allows it only to a superuser or a member of supabase_admin. If the apply role is neither, the pack says so (NOTICE) instead of failing:
-- supabase_admin objects in schema private cannot arise from this pack anyway (it creates everything as postgres), and the post-check proves no client default ACL exists in private.
DO $adp$
BEGIN
  IF to_regrole('supabase_admin') IS NOT NULL AND pg_has_role(current_user, 'supabase_admin', 'MEMBER') THEN
    EXECUTE 'ALTER DEFAULT PRIVILEGES FOR ROLE supabase_admin IN SCHEMA private REVOKE ALL ON FUNCTIONS FROM PUBLIC, anon, authenticated, service_role';
    EXECUTE 'ALTER DEFAULT PRIVILEGES FOR ROLE supabase_admin IN SCHEMA private REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated, service_role';
    EXECUTE 'ALTER DEFAULT PRIVILEGES FOR ROLE supabase_admin IN SCHEMA private REVOKE ALL ON SEQUENCES FROM PUBLIC, anon, authenticated, service_role';
    RAISE NOTICE '12A: default privileges for role supabase_admin in schema private revoked';
  ELSE
    RAISE NOTICE '12A: current_user is not a member of supabase_admin (or that role does not exist): ALTER DEFAULT PRIVILEGES FOR ROLE supabase_admin skipped; verified instead (post-check private.client_access) that no default ACL entry in schema private grants anything to PUBLIC or a client role';
  END IF;
END
$adp$;

-- 4. private.door_checkin_core: no grants to anyone but the owner (the two public wrappers are SECURITY DEFINER and run as the owner).
CREATE FUNCTION private.door_checkin_core(p_raw text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_handle  text;
  v_tok     text;
  v_n       int;
  o         record;
  v_at      timestamptz;
  v_status  text;
  v_tier    text;
  v_checked int;
  v_sold    int;
begin
  -- 1. authentication: a signed-in JWT subject is required. No uid, no information.
  if v_uid is null then
    return pg_catalog.jsonb_build_object('code', 'unauth');
  end if;

  -- 2. normalise the scanned payload: trim, strip ONE leading 'KIL-' (any case), trim again.
  v_tok := pg_catalog.regexp_replace(coalesce(p_raw, ''), '^\s+|\s+$', '', 'g');
  v_tok := pg_catalog.regexp_replace(v_tok, '^KIL-', '', 'i');
  v_tok := pg_catalog.regexp_replace(v_tok, '^\s+|\s+$', '', 'g');
  if v_tok = '' then
    return pg_catalog.jsonb_build_object('code', 'empty');
  end if;
  if pg_catalog.length(v_tok) > 128 then
    return pg_catalog.jsonb_build_object('code', 'invalid');
  end if;

  -- 3. caller's door handle. NULL and '' are both "no handle".
  select nullif(u.handle, '') into v_handle from public.app_users u where u.id = v_uid;

  -- 4. token lookup. qr_token carries no UNIQUE constraint, so a duplicated token is refused, never guessed.
  select pg_catalog.count(*) into v_n
    from (select 1 from public.event_orders x where x.qr_token = v_tok limit 2) d;
  if v_n = 0 or v_n > 1 then
    return pg_catalog.jsonb_build_object('code', 'invalid');
  end if;

  select o2.id, o2.event_id, o2.tier_id, o2.qty, o2.status, o2.checked_in_at,
         e.title as event_title, nullif(e.owner_handle, '') as owner_handle
    into o
    from public.event_orders o2
    join public.events e on e.id = o2.event_id
   where o2.qr_token = v_tok;

  -- 5. owner authorisation: BOTH sides must be non-null/non-empty, then case-insensitive equality.
  if v_handle is null or o.owner_handle is null
     or pg_catalog.lower(v_handle) <> pg_catalog.lower(o.owner_handle) then
    return pg_catalog.jsonb_build_object('code', 'forbidden');
  end if;

  select t.name into v_tier from public.ticket_tiers t where t.id = o.tier_id;
  v_tier := coalesce(v_tier, 'GA');

  -- 6. cheap pre-classification (the UPDATE below is the real gate).
  v_status := o.status;
  v_at := o.checked_in_at;
  if v_status is distinct from 'paid' or v_at is not null then
    -- fall through to the final classification below without attempting admission
    null;
  else
    -- 7. ATOMIC single admission: one statement decides. status, prior admission and ownership are all
    --    re-evaluated on the locked row, so concurrent scans / a concurrent refund cannot both win.
    update public.event_orders eo
       set checked_in_at = pg_catalog.now()
     where eo.id = o.id
       and eo.checked_in_at is null
       and eo.status = 'paid'
       and exists (select 1 from public.events ev
                    where ev.id = eo.event_id
                      and nullif(ev.owner_handle, '') is not null
                      and pg_catalog.lower(ev.owner_handle) = pg_catalog.lower(v_handle))
    returning eo.checked_in_at into v_at;
    if found then
      select pg_catalog.count(*) filter (where z.checked_in_at is not null), pg_catalog.count(*)
        into v_checked, v_sold
        from public.event_orders z where z.event_id = o.event_id and z.status = 'paid';
      return pg_catalog.jsonb_build_object('code', 'admitted', 'event_title', o.event_title, 'tier', v_tier,
               'qty', o.qty, 'checked_in_at', v_at, 'checked_in', v_checked, 'sold', v_sold);
    end if;
    -- lost the race (or status/ownership changed since the read): re-read the committed row
    select z.status, z.checked_in_at into v_status, v_at from public.event_orders z where z.id = o.id;
    if not found then
      return pg_catalog.jsonb_build_object('code', 'invalid');
    end if;
    if v_status = 'paid' and v_at is null then
      return pg_catalog.jsonb_build_object('code', 'forbidden');   -- ownership changed under us
    end if;
  end if;

  select pg_catalog.count(*) filter (where z.checked_in_at is not null), pg_catalog.count(*)
    into v_checked, v_sold
    from public.event_orders z where z.event_id = o.event_id and z.status = 'paid';

  if v_status = 'checked_in' or (v_status = 'paid' and v_at is not null) then
    return pg_catalog.jsonb_build_object('code', 'already_used', 'event_title', o.event_title, 'tier', v_tier,
             'qty', o.qty, 'checked_in_at', v_at, 'checked_in', v_checked, 'sold', v_sold);
  end if;

  return pg_catalog.jsonb_build_object('code', 'unpaid', 'order_status', v_status, 'event_title', o.event_title,
           'tier', v_tier, 'qty', o.qty, 'checked_in', v_checked, 'sold', v_sold);
end;
$function$;
REVOKE ALL ON FUNCTION private.door_checkin_core(text) FROM PUBLIC, anon, authenticated, service_role;

-- 5. hardened public.event_checkin_scan (CREATE OR REPLACE keeps owner; ACL is set explicitly: every client role revoked, then the intended EXECUTE granted)
CREATE OR REPLACE FUNCTION public.event_checkin_scan(p_qr_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r jsonb := private.door_checkin_core(p_qr_token);
  c text  := r->>'code';
begin
  -- Token-free, contact-free adapter over the shared core. Only these keys can ever appear:
  -- ok, result, message, event_title, tier, qty, checked_in_at.
  if c = 'admitted' then
    return pg_catalog.jsonb_build_object('ok', true, 'result', 'admitted', 'message', 'Admitted',
      'event_title', r->'event_title', 'tier', r->'tier', 'qty', r->'qty', 'checked_in_at', r->'checked_in_at');
  elsif c = 'already_used' then
    return pg_catalog.jsonb_build_object('ok', false, 'result', 'already_used', 'message', 'Already admitted.',
      'event_title', r->'event_title', 'tier', r->'tier', 'qty', r->'qty', 'checked_in_at', r->'checked_in_at');
  elsif c = 'unpaid' then
    return pg_catalog.jsonb_build_object('ok', false, 'result', 'unpaid',
      'message', 'This order is not paid (' || coalesce(r->>'order_status', 'unknown') || ').',
      'event_title', r->'event_title');
  elsif c = 'forbidden' then
    return pg_catalog.jsonb_build_object('ok', false, 'result', 'forbidden', 'message', 'You are not on the door for this event.');
  elsif c = 'invalid' then
    return pg_catalog.jsonb_build_object('ok', false, 'result', 'invalid', 'message', 'Not a KEEPITIL ticket.');
  elsif c = 'empty' then
    return pg_catalog.jsonb_build_object('ok', false, 'result', 'empty', 'message', 'No code scanned.');
  end if;
  return pg_catalog.jsonb_build_object('ok', false, 'result', 'unauth', 'message', 'Sign in to scan tickets.');
end;
$function$;
REVOKE ALL ON FUNCTION public.event_checkin_scan(text) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.event_checkin_scan(text) TO authenticated, service_role;

-- 6. POST-CHECKS (assert; a failure rolls the whole transaction back). State S1 = scan hardened + core present, ticket still ORIGINAL; private holds only its pre-existing objects + the core; the pre-existing tables are unchanged.
DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
