  UNION ALL SELECT 'scan.exec_public' AS name, coalesce((SELECT coalesce((SELECT bool_or(x.grantee = 0) FROM aclexplode(p.proacl) x), false)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.event_checkin_scan(text)')), 'ABSENT') AS actual
