  UNION ALL SELECT 'ticket.src_md5' AS name, coalesce((SELECT md5(p.prosrc) FROM pg_proc p WHERE p.oid = to_regprocedure('public.check_in_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'ticket.config' AS name, coalesce((SELECT coalesce((SELECT string_agg(c,',') FROM unnest(p.proconfig) c),'(none)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.check_in_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'ticket.secdef' AS name, coalesce((SELECT p.prosecdef::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.check_in_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'ticket.owner' AS name, coalesce((SELECT pg_get_userbyid(p.proowner)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.check_in_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'ticket.lang_ret' AS name, coalesce((SELECT (SELECT l.lanname FROM pg_language l WHERE l.oid=p.prolang)::text||'/'||p.prorettype::regtype::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.check_in_ticket(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'ticket.acl_sorted' AS name, coalesce((SELECT coalesce(CASE WHEN p.proacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(p.proacl) acl_e) END,'(default)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.check_in_ticket(text)')), 'ABSENT') AS actual
