  UNION ALL SELECT 'core.owner' AS name, coalesce((SELECT pg_get_userbyid(p.proowner)::text FROM pg_proc p WHERE p.oid = to_regprocedure('private.door_checkin_core(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'core.lang_ret' AS name, coalesce((SELECT (SELECT l.lanname FROM pg_language l WHERE l.oid=p.prolang)::text||'/'||p.prorettype::regtype::text FROM pg_proc p WHERE p.oid = to_regprocedure('private.door_checkin_core(text)')), 'ABSENT') AS actual
