  UNION ALL SELECT 'core.exec_service_role' AS name, coalesce((SELECT has_function_privilege('service_role', p.oid, 'EXECUTE')::text FROM pg_proc p WHERE p.oid = to_regprocedure('private.door_checkin_core(text)')), 'ABSENT') AS actual
