    (SELECT 'unexpected function(s): ' || string_agg(p.oid::regprocedure::text, ', ' ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace = s.oid AND p.oid <> to_regprocedure('private.door_checkin_core(text)')),
