  UNION ALL SELECT 'orders.columns_md5' AS name, coalesce((SELECT md5(string_agg(a.attname::text||':'||format_type(a.atttypid,a.atttypmod), ',' ORDER BY a.attname::text COLLATE "C")) FROM pg_attribute a WHERE a.attrelid = 'public.event_orders'::regclass AND a.attnum > 0 AND NOT a.attisdropped), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.acl_sorted' AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.policies_md5' AS name, coalesce((SELECT md5(string_agg(x, ',' ORDER BY x COLLATE "C")) FROM (SELECT p.policyname::text||'|'||p.cmd||'|'||(SELECT string_agg(r::text, ',' ORDER BY r::text COLLATE "C") FROM unnest(p.roles) r)||'|'||p.permissive AS x FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = 'event_orders') s), 'ABSENT') AS actual
