  UNION ALL SELECT 'orders.status_check' AS name, coalesce((SELECT count(*)::text FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype = 'c' AND pg_get_constraintdef(c.oid) ~ 'pending' AND pg_get_constraintdef(c.oid) ~ 'paid' AND pg_get_constraintdef(c.oid) ~ 'checked_in' AND pg_get_constraintdef(c.oid) ~ 'refunded' AND pg_get_constraintdef(c.oid) ~ 'cancelled' AND (SELECT count(*) FROM regexp_matches(pg_get_constraintdef(c.oid), '''[^'']*''', 'g')) = 5), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.check_count' AS name, coalesce((SELECT count(*)::text FROM pg_constraint c WHERE c.conrelid = 'public.event_orders'::regclass AND c.contype = 'c'), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.user_triggers' AS name, coalesce((SELECT count(*)::text FROM pg_trigger t WHERE t.tgrelid = 'public.event_orders'::regclass AND NOT t.tgisinternal), 'ABSENT') AS actual
  UNION ALL SELECT 'deps.columns_present' AS name, coalesce((SELECT count(*)::text FROM (VALUES ('events','id'),('events','slug'),('events','title'),('events','owner_handle'),('app_users','id'),('app_users','handle'),('ticket_tiers','id'),('ticket_tiers','name')) v(t,c) WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.'||v.t) AND a.attname = v.c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'deps.auth_uid' AS name, coalesce((SELECT count(*)::text FROM pg_proc p WHERE p.oid = to_regprocedure('auth.uid()')), 'ABSENT') AS actual
), e(name, expected) AS (VALUES
  ('scan.overloads', '1'),
  ('scan.src_md5', '3196a34cd3b118ca02c1250c3816eb18'),
  ('scan.config', 'search_path=""'),
  ('scan.secdef', 'true'),
  ('scan.owner', 'postgres'),
  ('scan.lang_ret', 'plpgsql/jsonb'),
  ('scan.acl_sorted', '{authenticated=X/postgres,postgres=X/postgres,service_role=X/postgres}'),
  ('scan.exec_anon', 'false'),
  ('scan.exec_authenticated', 'true'),
  ('scan.exec_service_role', 'true'),
  ('scan.exec_public', 'false'),
