  ('core.overloads', '1'),
  ('core.src_md5', '809f6c9c2a7a26f50ef88dad46d4edc3'),
  ('core.config', 'search_path=""'),
  ('core.secdef', 'true'),
  ('core.owner', 'postgres'),
  ('core.lang_ret', 'plpgsql/jsonb'),
  ('core.nonowner_grants', '0'),
  ('core.exec_anon', 'false'),
  ('core.exec_authenticated', 'false'),
  ('core.exec_service_role', 'false'),
  ('private.contents', 'ok'),
  ('private.client_access', 'none'),
  ('orders.relkind_rls', 'r/true/false'),
  ('orders.columns_md5', '466de103365b91e19b05b5d29da153ad'),
  ('orders.acl_sorted', '{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}'),
  ('orders.policies_md5', '328eefa85ed838c92611a30808ff9a9a'),
  ('orders.constraints', 'f:events:c:event_id,f:ticket_tiers:n:tier_id,p:-:-:id'),
